from pathlib import Path
p=Path("runtime/src/builtin_number.c")
s=p.read_text()
def rb(start,end,repl):
    global s
    a=s.index(start); b=s.index(end,a); s=s[:a]+repl+s[b:]
def once(old,new):
    global s
    assert s.count(old)==1, (old, s.count(old))
    s=s.replace(old,new,1)
once('#include "heap_string.h"\n', '#include "heap_string.h"\n#include "number_format.h"\n')
rb('static MalValue mal_builtin_number_constructor(', '/**\n * Spec thisNumberValue', 'static MalValue mal_builtin_number_constructor(\n    MalVm *vm,\n    MalValue this_value,\n    const MalValue *args,\n    i32 arg_count,\n    MalValue new_target,\n    MalValue callee\n) {\n    (void) this_value;\n    (void) callee;\n    MalValue number;\n    if (arg_count == 0) {\n        number = mal_value_from_i32(0);\n    } else if (mal_ops_is_number(args[0])) {\n        // A Number primitive already has the exact result representation. Keep\n        // int32, f64, NaN, infinities, and either -0 encoding unchanged.\n        number = args[0];\n    } else if (mal_value_is_symbol(args[0])) {\n        mal_vm_throw_error(\n            vm,\n            MAL_INTRINSIC_TYPE_ERROR_PROTOTYPE,\n            "Cannot convert a Symbol value to a number"\n        );\n        return mal_value_new_undefined();\n    } else if (mal_value_is_object(args[0])) {\n        // ToNumber on an object first runs ToPrimitive(number) through the\n        // shared coercion path (valueOf/toString/@@toPrimitive), which may throw.\n        f64 primitive;\n        if (!mal_vm_to_number(vm, args[0], &primitive)) {\n            return mal_value_new_undefined();\n        }\n        number = mal_ops_number_value(primitive);\n    } else {\n        number = mal_ops_number_value(mal_ops_to_number(args[0]));\n    }\n\n    if (mal_value_is_undefined(new_target)) {\n        return number;\n    }\n\n    MalObject *prototype;\n    if (!mal_vm_get_prototype_from_constructor(\n            vm, new_target, MAL_INTRINSIC_NUMBER_PROTOTYPE, &prototype)) {\n        return mal_value_new_undefined();\n    }\n\n    return mal_value_from_primitive_wrapper(mal_primitive_wrapper_object_new(\n        &vm->heap,\n        prototype,\n        MAL_PRIMITIVE_WRAPPER_NUMBER,\n        number\n    ));\n}\n\n')
rb('/**\n * Spec thisNumberValue', 'static MalValue mal_builtin_parse_int(', '/** Unwrap thisNumberValue while preserving its exact internal Number encoding. */\nstatic bool mal_builtin_number_this_value(\n    MalVm *vm,\n    MalValue this_value,\n    MalValue *out\n) {\n    if (!mal_value_this_number_value(this_value, out)) {\n        mal_vm_throw_error(\n            vm,\n            MAL_INTRINSIC_TYPE_ERROR_PROTOTYPE,\n            "Number.prototype method called on incompatible receiver"\n        );\n        return false;\n    }\n    return true;\n}\n\n/** Unwrap thisNumberValue for methods that need native floating-point arithmetic. */\nstatic bool mal_builtin_number_this(MalVm *vm, MalValue this_value, f64 *out) {\n    MalValue primitive;\n    if (!mal_builtin_number_this_value(vm, this_value, &primitive)) {\n        return false;\n    }\n    *out = mal_ops_number_as_f64(primitive);\n    return true;\n}\n\n/** Base-10 Number::toString without the generic printf/parse precision search. */\nstatic MalString *mal_builtin_number_decimal_string(MalVm *vm, MalValue value) {\n    if (mal_value_is_f64(value)) {\n        f64 number = mal_value_to_f64(value);\n        if (number != 0.0) {\n            byte buffer[32];\n            usize length = mal_number_format_shortest(number, buffer);\n            return mal_string_new_ascii(&vm->heap, buffer, length);\n        }\n    }\n    return mal_ops_to_string(&vm->heap, value);\n}\n\nstatic MalValue mal_builtin_number_is_nan(\n    MalVm *vm,\n    MalValue this_value,\n    const MalValue *args,\n    i32 arg_count,\n    MalValue new_target,\n    MalValue callee\n) {\n    (void) vm;\n    (void) this_value;\n    (void) new_target;\n    (void) callee;\n    return mal_value_new_boolean(arg_count >= 1 && mal_value_is_nan(args[0]));\n}\n\nstatic bool mal_builtin_number_value_is_finite(MalValue value) {\n    // Genuine f64 values exclude all-ones exponents; NaN and infinities use\n    // explicit static encodings. Every f64 accepted here is therefore finite.\n    return mal_value_is_int32(value) ||\n        mal_value_is_f64(value) ||\n        value == MAL_VALUE_NEGATIVE_ZERO;\n}\n\nstatic MalValue mal_builtin_number_is_finite(\n    MalVm *vm,\n    MalValue this_value,\n    const MalValue *args,\n    i32 arg_count,\n    MalValue new_target,\n    MalValue callee\n) {\n    (void) vm;\n    (void) this_value;\n    (void) new_target;\n    (void) callee;\n    return mal_value_new_boolean(\n        arg_count >= 1 && mal_builtin_number_value_is_finite(args[0]));\n}\n\nstatic bool mal_builtin_number_value_is_integer(MalValue value) {\n    if (mal_value_is_int32(value) || value == MAL_VALUE_NEGATIVE_ZERO) {\n        return true;\n    }\n    if (!mal_value_is_f64(value)) {\n        return false;\n    }\n    f64 number = mal_value_to_f64(value);\n    return trunc(number) == number;\n}\n\nstatic MalValue mal_builtin_number_is_integer(\n    MalVm *vm,\n    MalValue this_value,\n    const MalValue *args,\n    i32 arg_count,\n    MalValue new_target,\n    MalValue callee\n) {\n    (void) vm;\n    (void) this_value;\n    (void) new_target;\n    (void) callee;\n    return mal_value_new_boolean(\n        arg_count >= 1 && mal_builtin_number_value_is_integer(args[0]));\n}\n\nstatic MalValue mal_builtin_number_is_safe_integer(\n    MalVm *vm,\n    MalValue this_value,\n    const MalValue *args,\n    i32 arg_count,\n    MalValue new_target,\n    MalValue callee\n) {\n    (void) vm;\n    (void) this_value;\n    (void) new_target;\n    (void) callee;\n    if (arg_count < 1) {\n        return mal_value_new_boolean(false);\n    }\n    MalValue value = args[0];\n    if (mal_value_is_int32(value) || value == MAL_VALUE_NEGATIVE_ZERO) {\n        return mal_value_new_boolean(true);\n    }\n    if (!mal_value_is_f64(value)) {\n        return mal_value_new_boolean(false);\n    }\n    f64 number = mal_value_to_f64(value);\n    return mal_value_new_boolean(\n        number >= MAL_NUMBER_MIN_SAFE_INTEGER &&\n        number <= MAL_NUMBER_MAX_SAFE_INTEGER &&\n        trunc(number) == number\n    );\n}\n\n')
rb('static MalValue mal_builtin_number_prototype_to_string(', 'static MalValue mal_builtin_number_prototype_to_locale_string(', 'static MalValue mal_builtin_number_prototype_to_string(\n    MalVm *vm,\n    MalValue this_value,\n    const MalValue *args,\n    i32 arg_count,\n    MalValue new_target,\n    MalValue callee\n) {\n    (void) new_target;\n    (void) callee;\n    MalValue primitive;\n    if (!mal_builtin_number_this_value(vm, this_value, &primitive)) {\n        return mal_value_new_undefined();\n    }\n\n    f64 radix = 10;\n    if (arg_count >= 1 && !mal_value_is_undefined(args[0])) {\n        f64 raw;\n        if (!mal_vm_to_number(vm, args[0], &raw)) {\n            return mal_value_new_undefined();\n        }\n        radix = mal_ops_number_to_integer_or_infinity(raw);\n    }\n    if (radix < 2 || radix > 36) {\n        mal_vm_throw_error(\n            vm,\n            MAL_INTRINSIC_RANGE_ERROR_PROTOTYPE,\n            "toString() radix must be between 2 and 36"\n        );\n        return mal_value_new_undefined();\n    }\n\n    i32 int_radix = (i32) radix;\n    f64 number = mal_ops_number_as_f64(primitive);\n    if (int_radix == 10 || !isfinite(number)) {\n        return mal_value_from_string(mal_builtin_number_decimal_string(vm, primitive));\n    }\n    return mal_value_from_string(\n        mal_builtin_number_radix_string(&vm->heap, number, int_radix));\n}\n\n')
rb('static MalValue mal_builtin_number_prototype_to_fixed(', 'void mal_builtin_number_install(', 'static MalValue mal_builtin_number_prototype_to_fixed(\n    MalVm *vm,\n    MalValue this_value,\n    const MalValue *args,\n    i32 arg_count,\n    MalValue new_target,\n    MalValue callee\n) {\n    (void) new_target;\n    (void) callee;\n    f64 number;\n    if (!mal_builtin_number_this(vm, this_value, &number)) {\n        return mal_value_new_undefined();\n    }\n\n    f64 digits = 0;\n    if (arg_count >= 1 && !mal_value_is_undefined(args[0])) {\n        f64 raw;\n        if (!mal_vm_to_number(vm, args[0], &raw)) {\n            return mal_value_new_undefined();\n        }\n        digits = mal_ops_number_to_integer_or_infinity(raw);\n    }\n    if (digits < 0 || digits > 100) {\n        mal_vm_throw_error(\n            vm,\n            MAL_INTRINSIC_RANGE_ERROR_PROTOTYPE,\n            "toFixed() digits argument must be between 0 and 100"\n        );\n        return mal_value_new_undefined();\n    }\n\n    if (!isfinite(number) || fabs(number) >= 1e21) {\n        return mal_value_from_string(\n            mal_builtin_number_decimal_string(vm, mal_ops_number_value(number)));\n    }\n\n    byte buffer[160];\n    usize length = mal_number_format_fixed(number, (i32) digits, buffer);\n    return mal_value_from_string(\n        mal_string_new_ascii(&vm->heap, buffer, length));\n}\n\nstatic MalValue mal_builtin_number_prototype_to_exponential(\n    MalVm *vm,\n    MalValue this_value,\n    const MalValue *args,\n    i32 arg_count,\n    MalValue new_target,\n    MalValue callee\n) {\n    (void) new_target;\n    (void) callee;\n    f64 number;\n    if (!mal_builtin_number_this(vm, this_value, &number)) {\n        return mal_value_new_undefined();\n    }\n\n    bool digits_undefined = arg_count < 1 || mal_value_is_undefined(args[0]);\n    f64 digits = 0;\n    if (!digits_undefined) {\n        f64 raw;\n        if (!mal_vm_to_number(vm, args[0], &raw)) {\n            return mal_value_new_undefined();\n        }\n        digits = mal_ops_number_to_integer_or_infinity(raw);\n    }\n    if (!isfinite(number)) {\n        return mal_value_from_string(\n            mal_builtin_number_decimal_string(vm, mal_ops_number_value(number)));\n    }\n    if (!digits_undefined && (digits < 0 || digits > 100)) {\n        mal_vm_throw_error(\n            vm,\n            MAL_INTRINSIC_RANGE_ERROR_PROTOTYPE,\n            "toExponential() argument must be between 0 and 100"\n        );\n        return mal_value_new_undefined();\n    }\n\n    byte buffer[160];\n    usize length = mal_number_format_exponential(\n        number, (i32) digits, digits_undefined, buffer);\n    return mal_value_from_string(\n        mal_string_new_ascii(&vm->heap, buffer, length));\n}\n\nstatic MalValue mal_builtin_number_prototype_to_precision(\n    MalVm *vm,\n    MalValue this_value,\n    const MalValue *args,\n    i32 arg_count,\n    MalValue new_target,\n    MalValue callee\n) {\n    (void) new_target;\n    (void) callee;\n    MalValue primitive;\n    if (!mal_builtin_number_this_value(vm, this_value, &primitive)) {\n        return mal_value_new_undefined();\n    }\n    if (arg_count < 1 || mal_value_is_undefined(args[0])) {\n        return mal_value_from_string(mal_builtin_number_decimal_string(vm, primitive));\n    }\n\n    f64 raw;\n    if (!mal_vm_to_number(vm, args[0], &raw)) {\n        return mal_value_new_undefined();\n    }\n    f64 precision = mal_ops_number_to_integer_or_infinity(raw);\n    f64 number = mal_ops_number_as_f64(primitive);\n    if (!isfinite(number)) {\n        return mal_value_from_string(mal_builtin_number_decimal_string(vm, primitive));\n    }\n    if (precision < 1 || precision > 100) {\n        mal_vm_throw_error(\n            vm,\n            MAL_INTRINSIC_RANGE_ERROR_PROTOTYPE,\n            "toPrecision() argument must be between 1 and 100"\n        );\n        return mal_value_new_undefined();\n    }\n\n    byte buffer[160];\n    usize length = mal_number_format_precision(number, (i32) precision, buffer);\n    return mal_value_from_string(\n        mal_string_new_ascii(&vm->heap, buffer, length));\n}\n\nstatic MalValue mal_builtin_number_prototype_value_of(\n    MalVm *vm,\n    MalValue this_value,\n    const MalValue *args,\n    i32 arg_count,\n    MalValue new_target,\n    MalValue callee\n) {\n    (void) args;\n    (void) arg_count;\n    (void) new_target;\n    (void) callee;\n    MalValue primitive;\n    return mal_builtin_number_this_value(vm, this_value, &primitive)\n        ? primitive\n        : mal_value_new_undefined();\n}\n\n')
p.write_text(s)
